use std::{fs,path::Path};#[path="runtime.rs"]mod mission_outcome;use mission_outcome::*;
fn main(){let w=std::env::args().nth(1).unwrap();let w=Path::new(&w);let data=fs::read(w.join("input.bin")).unwrap();let mut output=Vec::new();for chunk in data.chunks_exact(7252){let players:[[u8;1805];4]=std::array::from_fn(|i|chunk[i*1805..(i+1)*1805].try_into().unwrap());let b=&chunk[7220..];let u16at=|i|u16::from_le_bytes(b[i..i+2].try_into().unwrap());let u32at=|i|u32::from_le_bytes(b[i..i+4].try_into().unwrap());let context=MissionOutcomeContext{flags:b[0],mode:b[1],active:b[2],selected:b[3],mission_counter:u32at(4),frame:u32at(8),target_count:u16at(12),mission_limit:u16at(14),mission_timer:u16at(16),terrain_count:b[18],terrain_limit:u32at(19)as i32,field_34b9:b[23]};
let result=evaluate(&players,&context,|id|if players[id as usize][0x6e2]==2{Err(())}else{Ok(players[id as usize][0x6e2]!=0)});let mut tail=[255u8;12];
match result{Ok(q)=>{output.extend(q.scan.players.concat());tail[0]=q.flags_after;tail[1]=match q.outcome{MissionOutcome::Running=>0,MissionOutcome::Won{..}=>1,MissionOutcome::Lost{..}=>2};tail[2]=q.scan.winner.unwrap_or(255);tail[3]=q.scan.capability_queries.len()as u8;for(i,id)in q.scan.capability_queries.iter().enumerate(){tail[4+i]=*id}tail[8]=u8::from(q.result_request.is_some());},Err(e)=>{output.extend(players.concat());tail[0]=context.flags;tail[1]=match e{MissionOutcomeError::Unsupported(OutcomeBoundary::AlreadyTerminal)=>3,MissionOutcomeError::DeferredLandingRequired{..}=>4,MissionOutcomeError::Unsupported(OutcomeBoundary::AlternatePresentation)=>5,MissionOutcomeError::Capability(())=>6,_=>7};}}
output.extend(tail);}
fs::write(w.join("actual.bin"),output).unwrap();}
